CREATE POLICY "Users read their template files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'template-files' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users upload their template files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'template-files' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users delete their template files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'template-files' AND (storage.foldername(name))[1] = auth.uid()::text);